import React, { useEffect, useState } from "react";
import { fetchDeliveries } from "../api/deliveryApi";
import { Link } from "react-router-dom";

export default function DeliveryDashboard() {
  const [deliveries, setDeliveries] = useState<any[]>([]);

  useEffect(() => {
    fetchDeliveries().then((res) => setDeliveries(res.data));
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h1>Delivery Dashboard</h1>

      {/* ✅ Create Delivery Button */}
      <Link to="/create">
        <button style={{ padding: "10px", marginBottom: "20px" }}>
          + New Delivery
        </button>
      </Link>

      <ul>
        {deliveries.map((delivery) => (
          <li key={delivery._id}>
            <Link to={`/delivery/${delivery._id}`}>
              Delivery for {delivery.customerId} — Status: {delivery.status}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}
